    {
      "id": "E21b3cffc26bc1a43",
      "pertinente": true,
      "tipo": "explicacao_tecnica",
      "achados": [
        {
          "proposicao": "Em FPSO, o sistema de combate a incêndio é apresentado como um dos sistemas de utilidades, estabilidade e segurança, integrado ao conjunto de sistemas de apoio da unidade.",
          "trechos": [
            "E21b3cffc26bc1a43:1396:2095"
          ],
          "condicoes": [
            "descrição de configuração de uma unidade específica, P-35"
          ],
          "limites": [
            "não detalha filosofia da rede, bombas, redundância nem critérios hidráulicos",
            "listagem de sistemas não equivale a requisito normativo"
          ]
        },
        {
          "proposicao": "Após a identificação e hierarquização de cenários monitorados, ações de restabelecimento de integridade das camadas de proteção devem ser definidas conforme o tipo de elemento com desvio, visando levar os cenários à condição ALARP.",
          "trechos": [
            "E21b3cffc26bc1a43:1396:2095",
            "E21b3cffc26bc1a43:2095:2149"
          ],
          "condicoes": [
            "depende de identificação prévia de cenários monitorados e hierarquização de eventos topo"
          ],
          "limites": [
            "o trecho não especifica métodos de seleção de ações para o sistema de incêndio",
            "não informa parâmetros de desempenho ou aceitação da rede de incêndio"
          ]
        }
      ]
    },
    {
      "id": "E7a0e03debc4a88b8",
      "pertinente": true,
      "tipo": "recomendacao",
      "achados": [
        {
          "proposicao": "Os operadores devem garantir sistema de combate a incêndio adequado aos cenários identificados nas análises de risco.",
          "trechos": [
            "E7a0e03debc4a88b8:0:698"
          ],
          "condicoes": [
            "adequação vinculada aos cenários identificados nas análises de risco"
          ],
          "limites": [
            "o trecho não define como calcular adequação em termos de vazão, pressão, simultaneidade ou redundância"
          ]
        },
        {
          "proposicao": "Para tanques com requisito de instalação de câmara de espuma conforme normas brasileiras aplicáveis, a nota técnica indica verificação tanque a tanque e adequação quando necessária.",
          "trechos": [
            "E7a0e03debc4a88b8:0:698"
          ],
          "condicoes": [
            "aplicável especialmente a tanques que possuam tal requisito nas normas brasileiras aplicáveis"
          ],
          "limites": [
            "não identifica no trecho quais normas ou critérios técnicos específicos devem ser usados",
            "não extrapola para todos os tanques ou todas as instalações"
          ]
        },
        {
          "proposicao": "A nota técnica associa a aceitabilidade de soluções de segurança à demonstração baseada em risco e em estudos adequados quando se pretende justificar a ausência de determinados sistemas.",
          "trechos": [
            "E7a0e03debc4a88b8:698:1397",
            "E7a0e03debc4a88b8:1397:2095"
          ],
          "condicoes": [
            "trecho trata explicitamente de detecção de gases, mas explicita o uso de demonstração baseada em risco como critério de justificativa"
          ],
          "limites": [
            "a aplicação direta desse raciocínio ao sistema de combate a incêndio não está expressa no trecho",
            "fonte mais útil para filosofia de adequação por risco do que para hidráulica da rede"
          ]
        }
      ]
    },
    {
      "id": "E997297595068bf71",
