      "tipo": "resultado_experimental",
      "achados": [
        {
          "proposicao": "Em fiscalização da P-53, a ANP registrou degradação do sistema de combate a incêndio com água, incluindo indisponibilidade de PCVs associadas às BCIs, como parte dos motivos de interdição.",
          "trechos": [
            "E997297595068bf71:1398:2097"
          ],
          "condicoes": [
            "achado em unidade específica, em ação de fiscalização de 2024",
            "contexto de risco grave e iminente"
          ],
          "limites": [
            "o trecho não esclarece a função exata de cada PCV nem o impacto hidráulico quantitativo",
            "não informa arranjo de bombas, capacidade nominal, vazão ou pressão"
          ]
        },
        {
          "proposicao": "Degradações em tubulações e em estruturas de sustentação podem comprometer simultaneamente a contenção primária de fluidos perigosos e o sistema de combate a incêndio.",
          "trechos": [
            "E997297595068bf71:698:1398"
          ],
          "condicoes": [
            "observação feita em unidade com degradações significativas no topside"
          ],
          "limites": [
            "não há detalhamento de mecanismos específicos de falha da rede de incêndio",
            "não define critérios de inspeção ou reparo"
          ]
        },
        {
          "proposicao": "A confiabilidade do sistema fixo de CO2 e a adequação de tanques de químicos aos cenários de emergência apareceram como aspectos correlatos da filosofia global de proteção contra incêndio e emergência na unidade.",
          "trechos": [
            "E997297595068bf71:1398:2097"
          ],
          "condicoes": [
            "achados de auditoria/fiscalização em uma instalação específica"
          ],
          "limites": [
            "não fornece critérios de seleção de agente, dosagem ou cobertura",
            "não substitui fonte de projeto para sistemas fixos"
          ]
        }
      ]
    }
  ],
